package cse.oop2.hotelreservation.server; import java.net.ServerSocket; import java.net.Socket; public class ServerMain { public static void main(String[] args)throws Exception { UserRepository userRepo=new FileUserRepository(); AuthService authService=new AuthService(userRepo); RoomRepository roomRepo=new FileRoomRepository(); RoomService roomService=new RoomService(roomRepo); try(ServerSocket serverSocket=new ServerSocket(5000)){System.out.println("서버 시작: 5000 포트 대기중..."); while(true){Socket socket=serverSocket.accept();new ClientHandler(socket,authService,roomService).start();}} } }
